		(obj as IVmExternPath)?.InitNode(this);
		ExternPathStartNodes.Add(key, obj);
	}
	int num = sub.IndexOf('.') + 1;
	if (num != 0)
	{
		string key2 = sub.Substring(num);
		obj = (obj as IVmExternPath).GetExternNode(key2);
		(obj as IVmExternPath)?.InitNode();
	}
	return obj;
}

